type LogEntry={id:string;time:string;text:string;type:'info'|'success'|'warning'};
type BackendState={enabled:boolean;connectionStatus:'disconnected'|'connecting'|'qr'|'connected';currentQr:string;qrExpiresAt:string|null;accountPhone:string;accountName:string;lastConnectedAt:string|null;disconnectReason:string;disconnectKind:'none'|'intentional'|'abnormal'|'expired';isSending:boolean;progress:number;total:number;currentAction:string;logs:LogEntry[];campaignStatus:'idle'|'running'|'paused'|'completed'|'stopped';successCount:number;errorCount:number;errorDetails:{contact:string;error:string}[];runId:string;lastError:string;requiresNewQr:boolean;policyBlockReason:string;policyBlockedUntil:string|null};
type ContactList={id:string;name:string;contacts:string;unitId:string;createdAt:string};
type DeliveryDetail={contact:string;status:'AGUARDANDO'|'ENVIADO'|'FALHA';processedAt?:string;error?:string};
type DispatchHistory={id:string;name:string;createdAt:string;finishedAt?:string;unitId:string;total:number;processed?:number;successCount:number;errorCount:number;status:string;createdBy:string;createdByEmail?:string;contacts?:string[];message?:string;minDelay?:number;maxDelay?:number;simulateTyping?:boolean;confirmedOptIn?:boolean;deliveryDetails?:DeliveryDetail[];errorDetails?:{contact:string;error:string}[];interruptionReason?:string;processingError?:string};
type ServiceAvailability='checking'|'available'|'unavailable'|'not-configured';
type HighVolumeChallenge={id:string;phrase:string;expiresAt:string;recipientCount:number};
type DirectoryContact={id:string;name:string;maskedPhone:string;origin:string;consentAt:string;variables:Record<string,string>};
type ContactSegment={id:string;name:string;policy:'SNAPSHOT';contactCount:number};
type SavedMessageContent={id:string;name:string;message:string;kind:'DRAFT'|'TEMPLATE';updatedAt:string};
type CampaignMedia={id:string;type:'IMAGE'|'VIDEO';mimeType:string;sizeBytes:number;caption:string;order:number;originalName:string;previewUrl:string};
type ManagedCampaign={id:string;name:string;status:string;scheduledAt:string|null;timeZone?:string;recurrence?:string;approvalRequired?:boolean;createdAt:string;createdBy:string;createdByEmail?:string;totalRecipients:number;firstSentAt?:string};

const initialBackend:BackendState={enabled:false,connectionStatus:'disconnected',currentQr:'',qrExpiresAt:null,accountPhone:'',accountName:'',lastConnectedAt:null,disconnectReason:'',disconnectKind:'none',isSending:false,progress:0,total:0,currentAction:'Conecte o serviço para começar.',logs:[],campaignStatus:'idle',successCount:0,errorCount:0,errorDetails:[],runId:'',lastError:'',requiresNewQr:false,policyBlockReason:'',policyBlockedUntil:null};
const messageServiceUrl=String(import.meta.env.VITE_MESSAGE_SERVICE_URL||(import.meta.env.DEV?'http://127.0.0.1:3101':'')).replace(/\/$/,'');
const messageApi=(path:string)=>`${messageServiceUrl}/api/message-dispatch/${path}`;
const normalizeContacts=(value:string)=>{
  const raw=value.split(/[\n,;]+/).map(item=>item.trim()).filter(Boolean);
  const valid:string[]=[];const invalid:string[]=[];
  raw.forEach(item=>{let digits=item.replace(/\D/g,'');if(digits.startsWith('0'))digits=digits.slice(1);if(digits.length===10||digits.length===11)digits=`55${digits}`;(digits.length>=12&&digits.length<=13?valid:invalid).push(digits||item);});
  return {valid:[...new Set(valid)],invalid,duplicates:Math.max(0,valid.length-new Set(valid).size)};
};
const dateTime=(value:string)=>value?new Date(value).toLocaleString('pt-BR'):'—';

export default function MessageDispatchDashboard(){
  const {currentUser,systemUnits}=useStore();
  const confirmAction=useConfirmation();
  const startIdempotencyKey=useRef<string>(crypto.randomUUID());
  const [campaignName,setCampaignName]=useState('');
  const [qrSeconds,setQrSeconds]=useState(0);
  const [contacts,setContacts]=useState('');
  const [message,setMessage]=useState('');
  const [minDelay,setMinDelay]=useState(15);
  const [maxDelay,setMaxDelay]=useState(35);
  const [simulateTyping,setSimulateTyping]=useState(true);
  const [confirmedOptIn,setConfirmedOptIn]=useState(false);
  const [optInOrigin,setOptInOrigin]=useState('Cadastro no sistema');
  const [optInDate,setOptInDate]=useState(new Date().toISOString().slice(0,10));
  const [optInEvidence,setOptInEvidence]=useState('');
  const [legalBasis,setLegalBasis]=useState<'CONSENT'|'CONTRACT'|'LEGAL_OBLIGATION'|'LEGITIMATE_INTEREST'>('CONSENT');
  const [importRows,setImportRows]=useState<Record<string,unknown>[]>([]);
  const [importColumns,setImportColumns]=useState<string[]>([]);
  const [importMapping,setImportMapping]=useState({name:'',phone:'',origin:'',consentAt:'',evidence:'',variableColumns:[] as string[]});
  const [importPreview,setImportPreview]=useState<ReturnType<typeof mapMessageContactRows>|null>(null);
  const [importFileName,setImportFileName]=useState('');
  const [importedConsents,setImportedConsents]=useState<(ImportedMessageContact&{legalBasis:string})[]>([]);
  const [clientSearch,setClientSearch]=useState('');
  const [clientResults,setClientResults]=useState<DirectoryContact[]>([]);
  const [clientPage,setClientPage]=useState(1);
  const [clientTotalPages,setClientTotalPages]=useState(1);
  const [selectedClientIds,setSelectedClientIds]=useState<string[]>([]);
  const [segments,setSegments]=useState<ContactSegment[]>([]);
  const [directoryLoading,setDirectoryLoading]=useState(false);
  const [drafts,setDrafts]=useState<SavedMessageContent[]>([]);
  const [templates,setTemplates]=useState<SavedMessageContent[]>([]);
  const [previewPhone,setPreviewPhone]=useState('');
  const [activeDraftId,setActiveDraftId]=useState('');
  const [campaignMedia,setCampaignMedia]=useState<CampaignMedia[]>([]);
  const [mediaUploading,setMediaUploading]=useState(false);
  const [scheduledLocal,setScheduledLocal]=useState('');
  const [recurrence,setRecurrence]=useState<'NONE'|'DAILY'|'WEEKLY'|'MONTHLY'>('NONE');
  const [recurrenceEndsAt,setRecurrenceEndsAt]=useState('');
  const [approvalRequired,setApprovalRequired]=useState(false);
  const [managedCampaigns,setManagedCampaigns]=useState<ManagedCampaign[]>([]);
  const [unitId,setUnitId]=useState(()=>defaultUnitFor(currentUser));
  const [backend,setBackend]=useState(initialBackend);
  const [lists,setLists]=useState<ContactList[]>([]);
  const [history,setHistory]=useState<DispatchHistory[]>([]);
  const [feedback,setFeedback]=useState('');
  const [testPhone,setTestPhone]=useState('');
  const [testSending,setTestSending]=useState(false);
  const [highVolumeChallenge,setHighVolumeChallenge]=useState<HighVolumeChallenge|null>(null);
  const [highVolumeConfirmation,setHighVolumeConfirmation]=useState('');
  const [apiError,setApiError]=useState('');
  const [serviceAvailability,setServiceAvailability]=useState<ServiceAvailability>('checking');
  const parsed=useMemo(()=>normalizeContacts(contacts),[contacts]);
  const importedConsentPhones=useMemo(()=>new Set(importedConsents.map(item=>normalizeContacts(item.phone).valid[0]).filter(Boolean)),[importedConsents]);
  const variableNames=useMemo(()=>[...new Set(importedConsents.flatMap(item=>Object.keys(item.variables||{})))],[importedConsents]);
  const previewContact=useMemo(()=>importedConsents.find(item=>item.phone===previewPhone)||importedConsents[0],[importedConsents,previewPhone]);
  const needsDefaultConsent=parsed.valid.some(phone=>!importedConsentPhones.has(phone));
  const consentEvidenceReady=!needsDefaultConsent||Boolean(optInOrigin.trim()&&optInDate&&optInEvidence.trim());
  const percentage=backend.total?Math.round(backend.progress/backend.total*100):0;

  const { currentData: currentHistory, currentPage, totalPages, goToPage, totalItems } = usePagination(history, 10);

  useEffect(()=>onSnapshot(scopedCollectionQuery('message_contact_lists',currentUser),snapshot=>setLists(snapshot.docs.map(item=>({id:item.id,...item.data()} as ContactList)).sort((a,b)=>b.createdAt.localeCompare(a.createdAt)))),[currentUser]);
  useEffect(()=>onSnapshot(scopedCollectionQuery('message_dispatch_history',currentUser),snapshot=>setHistory(snapshot.docs.map(item=>({id:item.id,...item.data()} as DispatchHistory)).sort((a,b)=>b.createdAt.localeCompare(a.createdAt)).slice(0,20))),[currentUser]);
  useEffect(()=>{if(unitId==='ALL'){const first=systemUnits.find(item=>item.isActive!==false);if(first)setUnitId(first.id);}},[systemUnits,unitId]);
  useEffect(()=>{setClientResults([]);setSelectedClientIds([]);setClientPage(1);if(unitId==='ALL'||!messageServiceUrl){setSegments([]);return;}let active=true;void authenticatedApi.jsonWithoutLogout<ContactSegment[]>(`${messageApi('segments')}?unitId=${encodeURIComponent(unitId)}`).then(result=>{if(active)setSegments(result);}).catch(()=>{if(active)setSegments([]);});return()=>{active=false;};},[unitId]);
  useEffect(()=>{if(unitId==='ALL'||!messageServiceUrl){setDrafts([]);setTemplates([]);return;}let active=true;void authenticatedApi.jsonWithoutLogout<{drafts:SavedMessageContent[];templates:SavedMessageContent[]}>(`${messageApi('content')}?unitId=${encodeURIComponent(unitId)}`).then(result=>{if(active){setDrafts(result.drafts);setTemplates(result.templates);}}).catch(()=>{if(active){setDrafts([]);setTemplates([]);}});return()=>{active=false;};},[unitId]);
  useEffect(()=>{if(unitId==='ALL'||!messageServiceUrl){setManagedCampaigns([]);return;}let active=true;void authenticatedApi.jsonWithoutLogout<ManagedCampaign[]>(`${messageApi('campaigns')}?unitId=${encodeURIComponent(unitId)}`).then(result=>{if(active)setManagedCampaigns(result);}).catch(()=>{if(active)setManagedCampaigns([]);});return()=>{active=false;};},[unitId,backend.campaignStatus]);
  useEffect(()=>{setHighVolumeChallenge(null);setHighVolumeConfirmation('');},[campaignName,contacts,message,minDelay,maxDelay,simulateTyping,unitId]);
  useEffect(()=>{const update=()=>setQrSeconds(backend.qrExpiresAt?Math.max(0,Math.ceil((new Date(backend.qrExpiresAt).getTime()-Date.now())/1000)):0);update();const timer=setInterval(update,1000);return()=>clearInterval(timer);},[backend.qrExpiresAt]);
  useEffect(()=>{
    if(unitId==='ALL')return;
    let cancelled=false;let reconnectTimer:ReturnType<typeof setTimeout>|null=null;let controller:AbortController|null=null;let cursor='';
    const connectStream=async()=>{
      if(!messageServiceUrl){setServiceAvailability('not-configured');setBackend(initialBackend);setApiError('O endereço do serviço de mensagens não foi configurado neste ambiente. Informe VITE_MESSAGE_SERVICE_URL no deploy.');return;}
      controller=new AbortController();
      try{
        const health=await fetch(`${messageServiceUrl}/health`,{headers:{Accept:'application/json'},signal:controller.signal});
        if(!health.ok)throw new Error(`serviço respondeu com status ${health.status}`);
        const healthData=await health.json() as {status?:string;service?:string};
        if(healthData.status!=='ok'||healthData.service!=='message-dispatch')throw new Error('resposta de saúde inválida');
        const headers:Record<string,string>={Accept:'text/event-stream'};if(cursor)headers['Last-Event-ID']=cursor;
        const response=await authenticatedApi.requestWithoutLogout(`${messageApi('events')}?unitId=${encodeURIComponent(unitId)}`,{headers,signal:controller.signal});
        if(!response.body)throw new Error('O navegador não disponibilizou o canal em tempo real.');
        if(!cancelled){setServiceAvailability('available');setApiError('');}
        const reader=response.body.getReader(),decoder=new TextDecoder();let buffer='';
        while(!cancelled){const {done,value}=await reader.read();if(done)break;buffer+=decoder.decode(value,{stream:true}).replace(/\r\n/g,'\n');let boundary=buffer.indexOf('\n\n');while(boundary>=0){const frame=buffer.slice(0,boundary);buffer=buffer.slice(boundary+2);const idLine=frame.split('\n').find(line=>line.startsWith('id:'));const dataLines=frame.split('\n').filter(line=>line.startsWith('data:')).map(line=>line.slice(5).trim());if(idLine)cursor=idLine.slice(3).trim();if(dataLines.length){const event=JSON.parse(dataLines.join('\n')) as {id?:number;data?:BackendState};if(event.id!==undefined)cursor=String(event.id);if(event.data&&!cancelled){setBackend(event.data);setServiceAvailability('available');setApiError('');}}boundary=buffer.indexOf('\n\n');}}
        if(!cancelled)throw new Error('Canal em tempo real encerrado.');
      }catch(error){if(cancelled||controller?.signal.aborted)return;setServiceAvailability('unavailable');setApiError(`Reconectando ao serviço de mensagens. ${error instanceof Error?error.message:'Tente novamente em instantes.'}`);reconnectTimer=setTimeout(()=>void connectStream(),2000);}
    };
    void connectStream();return()=>{cancelled=true;controller?.abort();if(reconnectTimer)clearTimeout(reconnectTimer);};
  },[unitId]);

  const call=async(path:string,body?:object)=>{setFeedback('');return authenticatedApi.jsonWithoutLogout<Record<string,unknown>>(messageApi(path),{method:'POST',headers:{'Content-Type':'application/json'},body:body?JSON.stringify(body):undefined});};
  const uploadMedia=async(event:React.ChangeEvent<HTMLInputElement>)=>{const files=[...(event.target.files||[])];event.target.value='';if(!files.length)return;if(campaignMedia.length+files.length>5){setFeedback('É permitido anexar no máximo 5 arquivos por campanha.');return;}setMediaUploading(true);try{const added:CampaignMedia[]=[];for(const file of files){const allowed=['image/jpeg','image/png','image/webp','video/mp4','video/webm'];if(!allowed.includes(file.type))throw new Error(`${file.name}: use JPG, PNG, WebP, MP4 ou WebM.`);const limit=file.type.startsWith('image/')?8*1024*1024:25*1024*1024;if(!file.size||file.size>limit)throw new Error(`${file.name}: limite de ${limit/1024/1024} MB excedido.`);const signature=new Uint8Array(await file.slice(0,12).arrayBuffer());const valid=file.type==='image/jpeg'?(signature[0]===0xff&&signature[1]===0xd8&&signature[2]===0xff):file.type==='image/png'?(signature[0]===0x89&&signature[1]===0x50&&signature[2]===0x4e&&signature[3]===0x47):file.type==='image/webp'?(String.fromCharCode(...signature.slice(0,4))==='RIFF'&&String.fromCharCode(...signature.slice(8,12))==='WEBP'):file.type==='video/mp4'?String.fromCharCode(...signature.slice(4,8))==='ftyp':(signature[0]===0x1a&&signature[1]===0x45&&signature[2]===0xdf&&signature[3]===0xa3);if(!valid)throw new Error(`${file.name}: conteúdo incompatível com o formato informado.`);const response=await authenticatedApi.requestWithoutLogout(`${messageApi('media/upload')}?unitId=${encodeURIComponent(unitId)}`,{method:'POST',headers:{'Content-Type':'application/octet-stream','X-File-Name':encodeURIComponent(file.name),'X-File-Type':file.type,'X-Upload-Id':startIdempotencyKey.current,'X-Media-Order':String(campaignMedia.length+added.length)},body:file});const saved=await response.json() as Omit<CampaignMedia,'previewUrl'>;added.push({...saved,previewUrl:URL.createObjectURL(file)});}setCampaignMedia(current=>[...current,...added]);setFeedback(`${added.length} anexo(s) armazenado(s) com segurança.`);}catch(error){setFeedback(error instanceof Error?error.message:'Falha ao anexar mídia.');}finally{setMediaUploading(false);}};
  const removeMedia=async(item:CampaignMedia)=>{try{await call('media/delete',{unitId,mediaId:item.id});URL.revokeObjectURL(item.previewUrl);setCampaignMedia(current=>current.filter(media=>media.id!==item.id));setFeedback('Anexo removido.');}catch(error){setFeedback(error instanceof Error?error.message:'Falha ao remover anexo.');}};
  const moveMedia=(index:number,direction:-1|1)=>setCampaignMedia(current=>{const target=index+direction;if(target<0||target>=current.length)return current;const next=[...current];[next[index],next[target]]=[next[target],next[index]];return next.map((item,order)=>({...item,order}));});
  const searchClients=async(page=1)=>{setDirectoryLoading(true);try{const result=await authenticatedApi.jsonWithoutLogout<{items:DirectoryContact[];page:number;totalPages:number}>(`${messageApi('contacts')}?unitId=${encodeURIComponent(unitId)}&q=${encodeURIComponent(clientSearch)}&page=${page}&pageSize=8`);setClientResults(result.items);setClientPage(result.page);setClientTotalPages(result.totalPages);}catch(error){setFeedback(error instanceof Error?error.message:'Falha ao buscar clientes.');}finally{setDirectoryLoading(false);}};
  const loadSegments=async()=>{try{const result=await authenticatedApi.jsonWithoutLogout<ContactSegment[]>(`${messageApi('segments')}?unitId=${encodeURIComponent(unitId)}`);setSegments(result);}catch{setSegments([]);}};
  const loadSavedContent=async()=>{try{const result=await authenticatedApi.jsonWithoutLogout<{drafts:SavedMessageContent[];templates:SavedMessageContent[]}>(`${messageApi('content')}?unitId=${encodeURIComponent(unitId)}`);setDrafts(result.drafts);setTemplates(result.templates);}catch{setDrafts([]);setTemplates([]);}};
  const loadManagedCampaigns=async()=>{try{setManagedCampaigns(await authenticatedApi.jsonWithoutLogout<ManagedCampaign[]>(`${messageApi('campaigns')}?unitId=${encodeURIComponent(unitId)}`));}catch{setManagedCampaigns([]);}};
  const saveMessageContent=async(kind:'DRAFT'|'TEMPLATE')=>{if(!message.trim()){setFeedback('Digite uma mensagem antes de salvar.');return;}const current=kind==='DRAFT'?drafts.find(item=>item.id===activeDraftId):undefined;const name=prompt(kind==='DRAFT'?'Nome do rascunho:':'Nome do modelo:',current?.name||campaignName)?.trim();if(!name)return;try{const saved=await call(kind==='DRAFT'?'drafts':'templates',{unitId,...(kind==='DRAFT'&&activeDraftId?{id:activeDraftId}:{}),name,message}) as unknown as SavedMessageContent;if(kind==='DRAFT')setActiveDraftId(saved.id);await loadSavedContent();setFeedback(kind==='DRAFT'?'Rascunho salvo. Ele poderá ser retomado em outra sessão.':'Modelo adicionado à biblioteca desta unidade.');}catch(error){setFeedback(error instanceof Error?error.message:'Falha ao salvar conteúdo.');}};
  const applySavedContent=(item:SavedMessageContent)=>{setMessage(item.message);if(item.kind==='DRAFT'){setActiveDraftId(item.id);setCampaignName(item.name);}setFeedback(`${item.kind==='DRAFT'?'Rascunho':'Modelo'} carregado para edição.`);};
  const addDirectoryContacts=async(contactIds=selectedClientIds)=>{if(!contactIds.length){setFeedback('Selecione ao menos um cliente.');return;}try{const result=await call('contacts/resolve',{unitId,contactIds}) as {contacts?:ImportedMessageContact[]};const resolved=(result.contacts||[]).map(item=>({...item,legalBasis}));const existing=new Map(importedConsents.map(item=>[item.phone,item]));resolved.forEach(item=>existing.set(item.phone,item));const merged=[...existing.values()];setImportedConsents(merged);setContacts(current=>[...new Set([...normalizeContacts(current).valid,...resolved.map(item=>item.phone)])].join('\n'));setSelectedClientIds([]);setFeedback(`${resolved.length} clientes adicionados sem duplicar os contatos atuais.`);}catch(error){setFeedback(error instanceof Error?error.message:'Falha ao adicionar clientes.');}};
  const saveSegment=async()=>{if(!selectedClientIds.length){setFeedback('Selecione os clientes que formarão o segmento.');return;}const name=prompt('Nome do segmento:')?.trim();if(!name)return;try{await call('segments',{unitId,name,contactIds:selectedClientIds});await loadSegments();setFeedback('Segmento salvo como snapshot. Alterações futuras na base não mudam sua composição.');}catch(error){setFeedback(error instanceof Error?error.message:'Falha ao salvar segmento.');}};
  const useSegment=async(segmentId:string)=>{try{const result=await call('segments/resolve',{unitId,segmentId}) as {contacts?:ImportedMessageContact[]};const resolved=(result.contacts||[]).map(item=>({...item,legalBasis}));const existing=new Map(importedConsents.map(item=>[item.phone,item]));resolved.forEach(item=>existing.set(item.phone,item));setImportedConsents([...existing.values()]);setContacts(current=>[...new Set([...normalizeContacts(current).valid,...resolved.map(item=>item.phone)])].join('\n'));setFeedback(`${resolved.length} contatos do segmento foram adicionados sem duplicidade.`);}catch(error){setFeedback(error instanceof Error?error.message:'Falha ao carregar segmento.');}};
  const connect=async()=>{try{const reset=backend.requiresNewQr;await call(reset?'reset-session':'connect',{unitId});setFeedback(reset?'Sessão redefinida. Aguarde o novo QR Code.':'Conexão iniciada. Aguarde o QR Code.');}catch(error){setFeedback(error instanceof Error?error.message:'Falha ao conectar.');}};
  const connectionAction=async(action:'reconnect'|'disconnect'|'new-qr')=>{try{await call(action,{unitId});setFeedback(action==='disconnect'?'WhatsApp desconectado desta unidade.':action==='reconnect'?'Reconexão iniciada.':'Novo QR Code solicitado.');}catch(error){setFeedback(error instanceof Error?error.message:'Falha ao controlar a conexão.');}};
  const campaignPayload=()=>({campaignName,unitId,contacts:parsed.valid,recipientData:importedConsents.map(item=>({phone:item.phone,name:item.name,variables:item.variables})),message,mediaIds:campaignMedia.map(item=>item.id),scheduledAt:scheduledLocal?new Date(scheduledLocal).toISOString():null,timeZone:Intl.DateTimeFormat().resolvedOptions().timeZone||'America/Sao_Paulo',recurrence,recurrenceEndsAt:recurrenceEndsAt?new Date(`${recurrenceEndsAt}T23:59:59`).toISOString():null,approvalRequired,minDelay,maxDelay,simulateTyping,confirmedOptIn,idempotencyKey:startIdempotencyKey.current});
  const syncMedia=()=>campaignMedia.length?call('media/configure',{media:campaignMedia.map((item,index)=>({id:item.id,caption:item.caption,order:index}))}):Promise.resolve();
  const start=async()=>{if(!campaignName.trim()){setFeedback('Informe um nome para identificar o disparo.');return;}if(!parsed.valid.length){setFeedback('Inclua ao menos um contato válido.');return;}if(!message.trim()&&!campaignMedia.length){setFeedback('Digite uma mensagem ou adicione ao menos um anexo.');return;}if(recurrence!=='NONE'&&!scheduledLocal){setFeedback('Informe a data inicial da campanha recorrente.');return;}if(!confirmedOptIn){setFeedback('Confirme que os contatos autorizaram o recebimento.');return;}if(!consentEvidenceReady){setFeedback('Informe origem, data e evidência do consentimento para os contatos sem dados importados.');return;}const consentRecords=parsed.valid.map(phone=>importedConsents.find(item=>normalizeContacts(item.phone).valid[0]===phone)||{phone,origin:optInOrigin,consentAt:optInDate,evidence:optInEvidence,legalBasis});try{await syncMedia();if(parsed.valid.length>=50&&!highVolumeChallenge){const challenge=await call('high-volume-challenge',campaignPayload()) as unknown as HighVolumeChallenge;setHighVolumeChallenge(challenge);setHighVolumeConfirmation('');setFeedback(`Campanha de alto volume: digite exatamente “${challenge.phrase}” para liberar o envio.`);return;}const result=await call('start',{...campaignPayload(),consentRecords,highVolumeChallengeId:highVolumeChallenge?.id,highVolumeConfirmation}) as {reused?:boolean;status?:string};setFeedback(result.reused?'Esta solicitação já estava salva; nenhuma campanha duplicada foi criada.':result.status==='AGUARDANDO_APROVACAO'?'Campanha salva e enviada para aprovação de outro administrador.':result.status==='AGENDADA'?'Campanha agendada com sucesso.':'Campanha iniciada no serviço persistente.');if(!result.reused){startIdempotencyKey.current=crypto.randomUUID();setCampaignMedia(current=>{current.forEach(item=>URL.revokeObjectURL(item.previewUrl));return [];});setHighVolumeChallenge(null);setHighVolumeConfirmation('');await loadManagedCampaigns();}}catch(error){setFeedback(error instanceof Error?error.message:'Falha ao iniciar.');}};
  const sendTest=async()=>{if(!campaignName.trim()||!message.trim()||!parsed.valid.length){setFeedback('Informe o nome, a mensagem e a lista da campanha antes do envio de teste.');return;}if(!normalizeContacts(testPhone).valid.length){setFeedback('Informe um número de teste válido.');return;}setTestSending(true);try{await syncMedia();await call('test-send',{...campaignPayload(),testPhone});setFeedback('Mensagem e anexos de teste enviados. Nenhum destinatário da lista foi liberado.');}catch(error){setFeedback(error instanceof Error?error.message:'Falha no envio de teste.');}finally{setTestSending(false);}};
  const approveCampaign=async(campaignId:string)=>{try{await call('campaigns/approve',{unitId,campaignId});await loadManagedCampaigns();setFeedback('Campanha aprovada. Ela seguirá o horário programado.');}catch(error){setFeedback(error instanceof Error?error.message:'Falha ao aprovar campanha.');}};
  const cancelScheduledCampaign=async(campaign:ManagedCampaign)=>{const confirmed=await confirmAction({title:'Cancelar campanha',description:`Deseja cancelar “${campaign.name}” antes do primeiro envio?`,confirmText:'Cancelar campanha'});if(!confirmed)return;try{await call('campaigns/cancel',{unitId,campaignId:campaign.id,reason:'Cancelada pelo painel antes do primeiro envio.'});await loadManagedCampaigns();setFeedback('Campanha cancelada e registrada na auditoria.');}catch(error){setFeedback(error instanceof Error?error.message:'Falha ao cancelar campanha.');}};
  const duplicateCampaign=async(campaignId:string)=>{try{const copy=await call('campaigns/duplicate',{unitId,campaignId}) as {campaignName?:string;message?:string;contacts?:string[];recipientData?:(ImportedMessageContact&{legalBasis?:string})[];minDelay?:number;maxDelay?:number;simulateTyping?:boolean;idempotencyKey?:string};setCampaignName(copy.campaignName||'Cópia de campanha');setMessage(copy.message||'');setContacts((copy.contacts||[]).join('\n'));setImportedConsents((copy.recipientData||[]).map(item=>({...item,legalBasis:item.legalBasis||legalBasis})));setMinDelay(copy.minDelay||15);setMaxDelay(copy.maxDelay||35);setSimulateTyping(copy.simulateTyping!==false);setScheduledLocal('');setRecurrence('NONE');setRecurrenceEndsAt('');setApprovalRequired(false);startIdempotencyKey.current=copy.idempotencyKey||crypto.randomUUID();setFeedback('Configurações copiadas para uma nova campanha. IDs, estado e chave de idempotência foram renovados.');window.scrollTo({top:0,behavior:'smooth'});}catch(error){setFeedback(error instanceof Error?error.message:'Falha ao duplicar campanha.');}};
  const togglePause=async()=>{try{await call(backend.campaignStatus==='paused'?'resume':'pause',{unitId});setFeedback(backend.campaignStatus==='paused'?'Campanha retomada.':'Pausa solicitada. O envio que já estiver em andamento poderá terminar.');}catch(error){setFeedback(error instanceof Error?error.message:'Falha ao controlar campanha.');}};
  const stop=async()=>{const reason=prompt('Informe o motivo da interrupção:','Interrompida manualmente pelo operador.')?.trim();if(reason===undefined)return;try{await call('stop',{unitId,reason});}catch(error){setFeedback(error instanceof Error?error.message:'Falha ao interromper.');}};
  const saveList=async()=>{if(!parsed.valid.length){setFeedback('Não há contatos válidos para salvar.');return;}const name=prompt('Nome da lista de contatos:')?.trim();if(!name)return;const id=crypto.randomUUID();await setDoc(doc(db,'message_contact_lists',id),{name,contacts:parsed.valid.join('\n'),unitId,createdAt:new Date().toISOString(),createdBy:currentUser?.id||''});setFeedback('Lista salva no sistema.');};
  const importConsentSheet=async(event:React.ChangeEvent<HTMLInputElement>)=>{const file=event.target.files?.[0];event.target.value='';if(!file)return;try{const extension=validateMessageContactFile(file),content=await file.arrayBuffer();validateMessageContactContent(extension,content);const XLSX=await loadXlsx();const workbook=XLSX.read(content,{type:'array',cellDates:true});if(!workbook.SheetNames.length)throw new Error('A planilha não possui abas legíveis.');const rows=XLSX.utils.sheet_to_json<Record<string,unknown>>(workbook.Sheets[workbook.SheetNames[0]],{defval:'',raw:false});if(!rows.length)throw new Error('A primeira aba da planilha não possui contatos.');const columns=Object.keys(rows[0]);setImportRows(rows);setImportColumns(columns);setImportMapping(detectMessageContactMapping(columns));setImportPreview(null);setImportFileName(file.name);setFeedback(`${rows.length} linhas carregadas de ${file.name}. Revise o mapeamento antes de processar.`);}catch(error){setImportRows([]);setImportColumns([]);setImportPreview(null);setImportFileName('');setFeedback(error instanceof Error?error.message:'Não foi possível ler a planilha.');}};
  const prepareImportMapping=()=>{try{if(!importMapping.origin||!importMapping.consentAt||!importMapping.evidence)throw new Error('Mapeie telefone, origem, data e evidência do consentimento.');const preview=mapMessageContactRows(importRows,importMapping);setImportPreview(preview);setFeedback(`Prévia pronta: ${preview.contacts.length} válidos, ${preview.invalid.length} inválidos e ${preview.duplicates.length} duplicados.`);}catch(error){setFeedback(error instanceof Error?error.message:'Revise o mapeamento das colunas.');}};
  const confirmImportedContacts=async()=>{if(!importPreview?.contacts.length){setFeedback('A importação não possui contatos válidos para confirmar.');return;}const mapped=importPreview.contacts.map(item=>({...item,legalBasis}));try{await call('contacts/import',{unitId,contacts:mapped});setImportedConsents(mapped);setContacts(mapped.map(item=>item.phone).join('\n'));setFeedback(`${mapped.length} contatos confirmados e adicionados à base desta unidade. Inválidos e duplicados foram descartados.`);setImportPreview(null);}catch(error){setFeedback(error instanceof Error?error.message:'Falha ao salvar contatos importados.');}};
  const etaSeconds=Math.max(0,parsed.valid.length-(backend.isSending?backend.progress:0))*((minDelay+maxDelay)/2+(simulateTyping?Math.min(6,Math.max(1.2,message.length*.045)):0));
  const eta=etaSeconds>=3600?`${Math.floor(etaSeconds/3600)}h ${Math.ceil(etaSeconds%3600/60)}min`:etaSeconds>=60?`${Math.ceil(etaSeconds/60)} min`:`${Math.ceil(etaSeconds)}s`;
  const exportCampaign=async(item:DispatchHistory)=>{
    try{
      const XLSX=await loadXlsx();
      const workbook=XLSX.utils.book_new();
      const unitName=systemUnits.find(unit=>unit.id===item.unitId)?.name||(item.unitId==='ALL'?'Todas as unidades':item.unitId);
      const summary=[
        {Campo:'Campanha',Valor:item.name},{Campo:'Unidade',Valor:unitName},{Campo:'Status',Valor:item.status},
        {Campo:'Iniciada em',Valor:dateTime(item.createdAt)},{Campo:'Finalizada em',Valor:item.finishedAt?dateTime(item.finishedAt):'—'},
        {Campo:'Criada por',Valor:item.createdByEmail||item.createdBy||'—'},{Campo:'Total de destinatários',Valor:item.total},
        {Campo:'Processados',Valor:item.processed??item.successCount+item.errorCount},{Campo:'Enviadas',Valor:item.successCount},{Campo:'Falhas',Valor:item.errorCount},
        {Campo:'Pausa mínima (s)',Valor:item.minDelay??'—'},{Campo:'Pausa máxima (s)',Valor:item.maxDelay??'—'},
        {Campo:'Simulação de digitação',Valor:item.simulateTyping===undefined?'—':item.simulateTyping?'Sim':'Não'},
        {Campo:'Opt-in confirmado',Valor:item.confirmedOptIn===undefined?'—':item.confirmedOptIn?'Sim':'Não'},
        {Campo:'Motivo da interrupção',Valor:item.interruptionReason||'—'},{Campo:'Erro de processamento',Valor:item.processingError||'—'},
        {Campo:'Mensagem enviada',Valor:item.message||'Não armazenada em campanhas antigas'},
      ];
      const errorByContact=new Map((item.errorDetails||[]).map(detail=>[detail.contact,detail.error]));
      const details=item.deliveryDetails?.length?item.deliveryDetails:(item.contacts||[]).map(contact=>({contact,status:(errorByContact.has(contact)?'FALHA':'AGUARDANDO') as DeliveryDetail['status'],error:errorByContact.get(contact)}));
      const detailRows=details.map((detail,index)=>({Ordem:index+1,Contato:detail.contact,Status:detail.status,'Processado em':detail.processedAt?dateTime(detail.processedAt):'—',Erro:detail.error||errorByContact.get(detail.contact)||''}));
      XLSX.utils.book_append_sheet(workbook,XLSX.utils.json_to_sheet(summary),'Resumo');
      XLSX.utils.book_append_sheet(workbook,XLSX.utils.json_to_sheet(detailRows.length?detailRows:[{Ordem:'—',Contato:'Detalhes individuais não disponíveis para campanhas antigas',Status:item.status,'Processado em':'—',Erro:''}]),'Destinatários');
      const safeName=(item.name||'campanha').normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-zA-Z0-9_-]+/g,'_').replace(/^_+|_+$/g,'').slice(0,60)||'campanha';
      XLSX.writeFile(workbook,`relatorio_disparo_${safeName}_${item.createdAt.slice(0,10)}.xlsx`);
      setFeedback(`Relatório integral da campanha “${item.name}” baixado com sucesso.`);
    }catch(error){setFeedback(error instanceof Error?`Falha ao gerar relatório: ${error.message}`:'Falha ao gerar relatório.');}
  };

  return <div className="space-y-5">
    <AppPageHeader eyebrow="Comunicação" title="Disparo de mensagens" description="Prepare listas autorizadas, conecte o WhatsApp e acompanhe cada envio em tempo real." icon={<MessageCircle className="h-5 w-5"/>}/>
    {apiError&&<div className="flex gap-3 rounded-xl border border-amber-200 bg-amber-50 p-4 text-sm text-amber-800 dark:border-amber-900/50 dark:bg-amber-950/20 dark:text-amber-300"><AlertTriangle className="h-5 w-5 shrink-0"/><div><strong>{serviceAvailability==='not-configured'?'Serviço de mensagens não configurado':'Serviço de mensagens indisponível'}</strong><p className="mt-1 text-xs">{apiError}</p><p className="mt-1 text-xs">Os demais módulos podem ser usados normalmente.</p></div></div>}
    <div className="grid gap-5 xl:grid-cols-[minmax(0,1.1fr)_minmax(360px,.9fr)]">
      <div className="space-y-5">
        <AppCard className="p-4 sm:p-5"><AppSectionHeader title="Campanha e destinatários" description="Um número por linha. O sistema adiciona o código 55, remove duplicados e sinaliza inválidos."/><div className="mt-4 grid gap-4 sm:grid-cols-2"><Field label="Nome do disparo"><input className={appControlClass+' w-full'} value={campaignName} onChange={event=>setCampaignName(event.target.value)} placeholder="Ex.: Lembrete de retorno setembro" disabled={backend.isSending}/></Field><Field label="Unidade"><select className={appControlClass+' w-full'} value={unitId} onChange={event=>setUnitId(event.target.value)} disabled={backend.isSending}>{systemUnits.filter(item=>item.isActive!==false).map(item=><option key={item.id} value={item.id}>{item.name}</option>)}</select></Field></div><div className="mt-4"><div className="mb-2 flex flex-wrap items-center justify-between gap-2"><label className="text-xs font-bold">Contatos do WhatsApp</label><div className="flex gap-2"><AppButton onClick={()=>setContacts(parsed.valid.join('\n'))} disabled={backend.isSending}><ListFilter className="h-4 w-4"/>Limpar lista</AppButton><AppButton onClick={saveList} disabled={backend.isSending}><Save className="h-4 w-4"/>Salvar lista</AppButton></div></div><textarea className="min-h-44 w-full rounded-xl border border-gray-200 bg-white p-3 font-mono text-sm outline-none focus:border-[var(--theme-color)] dark:border-zinc-700 dark:bg-zinc-950" value={contacts} onChange={event=>setContacts(event.target.value)} placeholder={'5511999999999\n11988887777'} disabled={backend.isSending}/><div className="mt-2 flex flex-wrap gap-2"><AppBadge tone="success">{parsed.valid.length} válidos</AppBadge>{parsed.duplicates>0&&<AppBadge tone="warning">{parsed.duplicates} duplicados</AppBadge>}{parsed.invalid.length>0&&<AppBadge tone="danger">{parsed.invalid.length} inválidos</AppBadge>}</div>{lists.length>0&&<div className="mt-3 flex flex-wrap gap-2">{lists.slice(0,8).map(list=><span key={list.id} className="inline-flex items-center overflow-hidden rounded-lg border border-gray-200 dark:border-zinc-700"><button className="px-3 py-2 text-xs font-bold hover:bg-gray-50 dark:hover:bg-zinc-800" onClick={()=>{setContacts(list.contacts);if(list.unitId&&list.unitId!=='ALL')setUnitId(list.unitId);}}>{list.name}</button><button aria-label={`Excluir ${list.name}`} className="border-l border-gray-200 p-2 text-gray-400 hover:text-red-500 dark:border-zinc-700" onClick={async()=>{if(await confirmAction({title:'Excluir lista de contatos',description:`Deseja excluir a lista “${list.name}”? Esta ação não pode ser desfeita.`,confirmText:'Excluir lista'}))await deleteDoc(doc(db,'message_contact_lists',list.id));}}><Trash2 className="h-3.5 w-3.5"/></button></span>)}</div>}</div></AppCard>
        <AppCard className="p-4 sm:p-5"><AppSectionHeader title="Importar contatos e consentimentos" description="Aceita CSV, XLSX, XLS e ODS até 10 MB. Revise o mapeamento e a prévia antes de confirmar."/><label className="mt-4 inline-flex cursor-pointer items-center gap-2 rounded-xl border border-gray-200 px-4 py-2 text-xs font-bold hover:bg-gray-50 dark:border-zinc-700 dark:hover:bg-zinc-800"><Upload className="h-4 w-4"/>Selecionar planilha<input type="file" className="hidden" accept=".xlsx,.xls,.csv,.ods" onChange={event=>void importConsentSheet(event)} disabled={backend.isSending}/></label>{importFileName&&<span className="ml-3 text-xs text-gray-500 dark:text-zinc-400">{importFileName}</span>}{importColumns.length>0&&<><div className="mt-4 grid gap-3 sm:grid-cols-2">{([['name','Nome'],['phone','Telefone *'],['origin','Origem do opt-in *'],['consentAt','Data do opt-in *'],['evidence','Evidência *']] as const).map(([key,label])=><Field key={key} label={label}><select className={appControlClass+' w-full'} value={importMapping[key]} onChange={event=>{setImportMapping(current=>({...current,[key]:event.target.value}));setImportPreview(null);}}><option value="">Selecione a coluna</option>{importColumns.map(column=><option key={column} value={column}>{column}</option>)}</select></Field>)}</div><div className="mt-4"><span className="text-xs font-bold text-gray-600 dark:text-zinc-300">Variáveis personalizadas</span><div className="mt-2 flex flex-wrap gap-2">{importColumns.filter(column=>![importMapping.name,importMapping.phone,importMapping.origin,importMapping.consentAt,importMapping.evidence].includes(column)).map(column=><label key={column} className="inline-flex items-center gap-2 rounded-lg border border-gray-200 px-3 py-2 text-xs dark:border-zinc-700"><input type="checkbox" checked={importMapping.variableColumns.includes(column)} onChange={event=>{setImportMapping(current=>({...current,variableColumns:event.target.checked?[...current.variableColumns,column]:current.variableColumns.filter(item=>item!==column)}));setImportPreview(null);}}/>{column}</label>)}</div></div><AppButton className="mt-3" onClick={prepareImportMapping}><ListFilter className="h-4 w-4"/>Processar e revisar</AppButton>{importPreview&&<div className="mt-4 rounded-xl border border-gray-200 p-4 dark:border-zinc-700"><div className="flex flex-wrap gap-2"><AppBadge tone="success">{importPreview.contacts.length} válidos</AppBadge><AppBadge tone={importPreview.invalid.length?'danger':'neutral'}>{importPreview.invalid.length} inválidos</AppBadge><AppBadge tone={importPreview.duplicates.length?'warning':'neutral'}>{importPreview.duplicates.length} duplicados</AppBadge></div>{importPreview.invalid.length>0&&<p className="mt-3 text-xs text-red-600 dark:text-red-400">Linhas inválidas: {importPreview.invalid.slice(0,8).map(item=>`${item.row} (${item.value||'vazio'})`).join(', ')}{importPreview.invalid.length>8?'…':''}</p>}{importPreview.duplicates.length>0&&<p className="mt-2 text-xs text-amber-700 dark:text-amber-300">Duplicados: {importPreview.duplicates.slice(0,8).map(item=>`linha ${item.row}`).join(', ')}{importPreview.duplicates.length>8?'…':''}</p>}<AppButton className="mt-4" variant="primary" onClick={confirmImportedContacts} disabled={!importPreview.contacts.length}><CheckCircle2 className="h-4 w-4"/>Confirmar {importPreview.contacts.length} contatos</AppButton></div>}</>}</AppCard>
        <AppCard className="p-4 sm:p-5"><AppSectionHeader title="Mensagem" description="Use rascunhos, modelos e tags. A mensagem final será salva individualmente para cada destinatário."/><div className="mt-4 grid gap-2 sm:grid-cols-2"><select className={appControlClass+' w-full'} value="" onChange={event=>{const item=[...drafts,...templates].find(content=>content.id===event.target.value);if(item)applySavedContent(item);}}><option value="">Carregar rascunho ou modelo</option>{drafts.length>0&&<optgroup label="Rascunhos">{drafts.map(item=><option key={item.id} value={item.id}>{item.name}</option>)}</optgroup>}{templates.length>0&&<optgroup label="Modelos">{templates.map(item=><option key={item.id} value={item.id}>{item.name}</option>)}</optgroup>}</select><div className="flex gap-2"><AppButton className="flex-1" onClick={()=>void saveMessageContent('DRAFT')}><Save className="h-4 w-4"/>Salvar rascunho</AppButton><AppButton className="flex-1" onClick={()=>void saveMessageContent('TEMPLATE')}><Save className="h-4 w-4"/>Salvar modelo</AppButton></div></div><div className="mt-3 flex flex-wrap gap-2">{['primeiro_nome','segundo_nome','nome',...variableNames].map(tag=><button key={tag} type="button" onClick={()=>setMessage(current=>`${current}${current&&!current.endsWith(' ')?' ':''}{{${tag}}}`)} className="rounded-lg border border-gray-200 px-2.5 py-1.5 font-mono text-[11px] hover:border-[var(--theme-color)] dark:border-zinc-700">{`{{${tag}}}`}</button>)}</div><textarea className="mt-4 min-h-40 w-full rounded-xl border border-gray-200 bg-white p-3 text-sm outline-none focus:border-[var(--theme-color)] dark:border-zinc-700 dark:bg-zinc-950" value={message} maxLength={4096} onChange={event=>setMessage(event.target.value)} placeholder="Olá, {{primeiro_nome}}! Tudo bem?" disabled={backend.isSending}/><p className="mt-1 text-right text-[10px] text-gray-400">{message.length}/4096</p><div className="mt-4 rounded-xl border border-dashed border-gray-300 p-3 dark:border-zinc-700"><div className="flex flex-wrap items-center justify-between gap-2"><div><strong className="block text-xs">Imagens e vídeos</strong><span className="text-[10px] text-gray-400">Até 5 arquivos · imagens 8 MB · vídeos 25 MB</span></div><label className={`inline-flex cursor-pointer items-center gap-2 rounded-xl border border-gray-200 px-3 py-2 text-xs font-bold hover:border-[var(--theme-color)] dark:border-zinc-700 ${mediaUploading||campaignMedia.length>=5?'pointer-events-none opacity-50':''}`}><Upload className="h-4 w-4"/>{mediaUploading?'Enviando...':'Adicionar mídia'}<input type="file" multiple accept="image/jpeg,image/png,image/webp,video/mp4,video/webm" className="hidden" onChange={event=>void uploadMedia(event)} disabled={mediaUploading||backend.isSending||campaignMedia.length>=5}/></label></div>{campaignMedia.length>0&&<div className="mt-3 grid gap-3 sm:grid-cols-2">{campaignMedia.map((item,index)=><div key={item.id} className="overflow-hidden rounded-xl border border-gray-200 bg-gray-50 dark:border-zinc-700 dark:bg-zinc-900"><div className="relative aspect-video bg-black">{item.type==='IMAGE'?<img src={item.previewUrl} alt={item.originalName} className="h-full w-full object-contain"/>:<video src={item.previewUrl} controls className="h-full w-full object-contain"/>}<span className="absolute left-2 top-2 rounded-md bg-black/70 px-2 py-1 text-[9px] font-bold text-white">{item.type==='IMAGE'?<ImageIcon className="inline h-3 w-3"/>:<Video className="inline h-3 w-3"/>} {Math.ceil(item.sizeBytes/1024)} KB</span></div><div className="p-3"><p className="truncate text-xs font-bold" title={item.originalName}>{item.originalName}</p><input className={appControlClass+' mt-2 w-full'} value={item.caption} maxLength={1024} onChange={event=>setCampaignMedia(current=>current.map(media=>media.id===item.id?{...media,caption:event.target.value}:media))} placeholder="Legenda individual (aceita tags)"/><div className="mt-2 flex justify-end gap-1"><AppButton aria-label="Mover anexo para cima" onClick={()=>moveMedia(index,-1)} disabled={index===0}><ArrowUp className="h-3.5 w-3.5"/></AppButton><AppButton aria-label="Mover anexo para baixo" onClick={()=>moveMedia(index,1)} disabled={index===campaignMedia.length-1}><ArrowDown className="h-3.5 w-3.5"/></AppButton><AppButton aria-label="Remover anexo" onClick={()=>void removeMedia(item)}><Trash2 className="h-3.5 w-3.5"/></AppButton></div></div></div>)}</div>}</div>{importedConsents.length>0&&<div className="mt-3 rounded-xl border border-blue-200 bg-blue-50 p-3 dark:border-blue-900/50 dark:bg-blue-950/20"><div className="flex flex-col gap-2 sm:flex-row sm:items-center sm:justify-between"><strong className="text-xs text-blue-900 dark:text-blue-200">Pré-visualização com contato real</strong><select className={appControlClass} value={previewContact?.phone||''} onChange={event=>setPreviewPhone(event.target.value)}>{importedConsents.map(item=><option key={item.phone} value={item.phone}>{item.name||item.phone}</option>)}</select></div><p className="mt-3 whitespace-pre-wrap text-sm text-blue-950 dark:text-blue-100">{materializeMessage(message,{name:previewContact?.name,variables:previewContact?.variables})||'Digite a mensagem para visualizar.'}</p></div>}<div className="mt-4 grid gap-3 sm:grid-cols-3"><Field label="Pausa mínima (s)"><input type="number" min={8} max={120} className={appControlClass+' w-full'} value={minDelay} onChange={event=>setMinDelay(Math.max(8,Number(event.target.value)))} disabled={backend.isSending}/></Field><Field label="Pausa máxima (s)"><input type="number" min={minDelay} max={180} className={appControlClass+' w-full'} value={maxDelay} onChange={event=>setMaxDelay(Math.max(minDelay,Number(event.target.value)))} disabled={backend.isSending}/></Field><label className="flex items-end"><span className="flex h-10 w-full items-center gap-2 rounded-xl border border-gray-200 px-3 text-xs font-bold dark:border-zinc-700"><input type="checkbox" checked={simulateTyping} onChange={event=>setSimulateTyping(event.target.checked)} disabled={backend.isSending}/>Preparar digitação</span></label></div><label className="mt-4 flex items-start gap-3 rounded-xl border border-emerald-200 bg-emerald-50 p-3 text-xs text-emerald-900 dark:border-emerald-900/50 dark:bg-emerald-950/20 dark:text-emerald-200"><input className="mt-0.5" type="checkbox" checked={confirmedOptIn} onChange={event=>setConfirmedOptIn(event.target.checked)} disabled={backend.isSending}/><span><strong>Contatos autorizados</strong><br/>Confirmo que os destinatários aceitaram receber mensagens e podem solicitar o descadastramento.</span></label></AppCard>
        <AppCard className="p-4 sm:p-5"><AppSectionHeader title="Agendamento e aprovação" description="Programe o início no fuso local, configure recorrência e solicite dupla aprovação."/><div className="mt-4 grid gap-3 sm:grid-cols-2"><Field label="Início do envio"><input type="datetime-local" className={appControlClass+' w-full'} value={scheduledLocal} min={new Date(Date.now()+60_000-new Date().getTimezoneOffset()*60_000).toISOString().slice(0,16)} onChange={event=>setScheduledLocal(event.target.value)}/></Field><Field label="Recorrência"><select className={appControlClass+' w-full'} value={recurrence} onChange={event=>setRecurrence(event.target.value as typeof recurrence)}><option value="NONE">Não repetir</option><option value="DAILY">Diariamente</option><option value="WEEKLY">Semanalmente</option><option value="MONTHLY">Mensalmente</option></select></Field>{recurrence!=='NONE'&&<Field label="Repetir até"><input type="date" className={appControlClass+' w-full'} value={recurrenceEndsAt} onChange={event=>setRecurrenceEndsAt(event.target.value)}/></Field>}<label className="flex items-end"><span className="flex min-h-10 w-full items-center gap-2 rounded-xl border border-gray-200 px-3 text-xs font-bold dark:border-zinc-700"><input type="checkbox" checked={approvalRequired} onChange={event=>setApprovalRequired(event.target.checked)}/>Exigir aprovação de outro administrador</span></label></div><p className="mt-3 text-[10px] text-gray-400">Fuso utilizado: {Intl.DateTimeFormat().resolvedOptions().timeZone||'America/Sao_Paulo'}. Campanhas agendadas permanecem na fila mesmo após reinícios.</p></AppCard>`r`n        <AppCard className="p-4 sm:p-5"><AppSectionHeader title="Base legal e evidência" description="Estes dados serão vinculados aos contatos que não vieram da planilha."/><div className="mt-4 grid gap-3 sm:grid-cols-2"><Field label="Base legal"><select className={appControlClass+' w-full'} value={legalBasis} onChange={event=>setLegalBasis(event.target.value as typeof legalBasis)}><option value="CONSENT">Consentimento</option><option value="CONTRACT">Execução de contrato</option><option value="LEGAL_OBLIGATION">Obrigação legal</option><option value="LEGITIMATE_INTEREST">Legítimo interesse</option></select></Field><Field label="Origem"><input className={appControlClass+' w-full'} value={optInOrigin} onChange={event=>setOptInOrigin(event.target.value)} placeholder="Ex.: cadastro presencial"/></Field><Field label="Data do opt-in"><input type="date" className={appControlClass+' w-full'} value={optInDate} max={new Date().toISOString().slice(0,10)} onChange={event=>setOptInDate(event.target.value)}/></Field><Field label="Evidência / justificativa"><input className={appControlClass+' w-full'} value={optInEvidence} onChange={event=>setOptInEvidence(event.target.value)} placeholder="Ex.: aceite no formulário 123"/></Field></div></AppCard>
        <AppCard className="p-4 sm:p-5"><AppSectionHeader title="Clientes e segmentos" description="Busque somente na base da unidade selecionada. Os telefones permanecem mascarados até serem adicionados."/><div className="mt-4 flex flex-col gap-2 sm:flex-row"><input className={appControlClass+' min-w-0 flex-1'} value={clientSearch} onChange={event=>setClientSearch(event.target.value)} onKeyDown={event=>{if(event.key==='Enter')void searchClients(1);}} placeholder="Buscar cliente pelo nome"/><AppButton onClick={()=>void searchClients(1)} disabled={directoryLoading}><Users className="h-4 w-4"/>{directoryLoading?'Buscando...':'Buscar'}</AppButton></div>{clientResults.length>0&&<div className="mt-4 space-y-2">{clientResults.map(client=><label key={client.id} className="flex items-center gap-3 rounded-xl border border-gray-200 p-3 dark:border-zinc-700"><input type="checkbox" checked={selectedClientIds.includes(client.id)} onChange={event=>setSelectedClientIds(current=>event.target.checked?[...current,client.id]:current.filter(id=>id!==client.id))}/><span className="min-w-0 flex-1"><strong className="block truncate text-sm">{client.name||'Cliente sem nome'}</strong><span className="text-xs text-gray-400">{client.maskedPhone} · {client.origin||'Origem não informada'}</span></span></label>)}<div className="flex items-center justify-between text-xs"><AppButton onClick={()=>void searchClients(Math.max(1,clientPage-1))} disabled={clientPage<=1}>Anterior</AppButton><span>{clientPage} de {clientTotalPages}</span><AppButton onClick={()=>void searchClients(Math.min(clientTotalPages,clientPage+1))} disabled={clientPage>=clientTotalPages}>Próxima</AppButton></div></div>}{selectedClientIds.length>0&&<div className="mt-3 flex flex-wrap gap-2"><AppButton variant="primary" onClick={()=>void addDirectoryContacts()}><Users className="h-4 w-4"/>Adicionar {selectedClientIds.length}</AppButton><AppButton onClick={()=>void saveSegment()}><Save className="h-4 w-4"/>Salvar segmento</AppButton></div>}{segments.length>0&&<div className="mt-4 border-t border-gray-200 pt-4 dark:border-zinc-700"><span className="text-xs font-bold">Segmentos salvos — snapshot</span><div className="mt-2 flex flex-wrap gap-2">{segments.map(segment=><button key={segment.id} type="button" onClick={()=>void useSegment(segment.id)} className="rounded-lg border border-gray-200 px-3 py-2 text-xs font-bold hover:border-[var(--theme-color)] dark:border-zinc-700">{segment.name} · {segment.contactCount}</button>)}</div><p className="mt-2 text-[10px] text-gray-400">Snapshot: a composição permanece igual mesmo que a base de clientes seja alterada.</p></div>}</AppCard>
        <AppCard className="p-4 sm:p-5"><AppSectionHeader title="Envio de teste" description="Valide o conteúdo final em um único número. A lista da campanha não será liberada."/><div className="mt-4 flex flex-col gap-3 sm:flex-row"><input className={appControlClass+' min-w-0 flex-1'} value={testPhone} onChange={event=>setTestPhone(event.target.value)} placeholder="Ex.: 11999999999" disabled={backend.isSending||testSending}/><AppButton onClick={()=>void sendTest()} disabled={backend.connectionStatus!=='connected'||backend.isSending||testSending||!message.trim()}><Send className="h-4 w-4"/>{testSending?'Enviando...':'Enviar teste'}</AppButton></div></AppCard>
        {highVolumeChallenge&&<AppCard className="border-amber-300 bg-amber-50 p-4 dark:border-amber-800 dark:bg-amber-950/20 sm:p-5"><AppSectionHeader title="Confirmação de alto volume" description={`Esta campanha possui ${highVolumeChallenge.recipientCount} destinatários. A confirmação expira em ${dateTime(highVolumeChallenge.expiresAt)}.`}/><p className="mt-4 text-xs text-amber-900 dark:text-amber-200">Digite exatamente: <strong className="select-all font-mono">{highVolumeChallenge.phrase}</strong></p><input className={appControlClass+' mt-3 w-full font-mono'} value={highVolumeConfirmation} onChange={event=>setHighVolumeConfirmation(event.target.value)} placeholder={highVolumeChallenge.phrase}/></AppCard>}
      </div>
      <div className="space-y-5">
        <AppCard className="p-4 sm:p-5"><AppSectionHeader title="Conexão do WhatsApp" description="A sessão fica no servidor e o acesso é autorizado automaticamente pelo seu login."/><div className="mt-3 flex justify-end"><AppBadge tone={serviceAvailability==='available'?'success':serviceAvailability==='checking'?'warning':'danger'}>{serviceAvailability==='available'?'Serviço online':serviceAvailability==='checking'?'Verificando serviço':'Serviço offline'}</AppBadge></div><div className="mt-4 flex items-center justify-between gap-3 rounded-xl bg-gray-50 p-3 dark:bg-zinc-800/60"><div className="flex items-center gap-3">{backend.connectionStatus==='connected'?<Wifi className="h-5 w-5 text-emerald-500"/>:<WifiOff className="h-5 w-5 text-amber-500"/>}<div><strong className="block text-sm">{backend.connectionStatus==='connected'?'Conectado':backend.connectionStatus==='qr'?'Aguardando leitura':backend.connectionStatus==='connecting'?'Conectando...':'Desconectado'}</strong><span className="text-xs text-gray-400">{backend.currentAction}</span></div></div>{backend.connectionStatus!=='connected'&&<AppButton variant="primary" onClick={connect} disabled={serviceAvailability!=='available'||backend.connectionStatus==='connecting'}><Link2 className="h-4 w-4"/>{backend.requiresNewQr?'Gerar novo QR':'Conectar'}</AppButton>}</div>{backend.lastError&&<p className="mt-3 rounded-lg bg-amber-50 p-3 text-xs text-amber-800 dark:bg-amber-950/30 dark:text-amber-300">{backend.lastError}</p>}{backend.currentQr&&<div className="mt-4 flex flex-col items-center rounded-xl border border-dashed border-gray-300 p-4 dark:border-zinc-700"><img src={backend.currentQr} alt="QR Code para conectar o WhatsApp" className="h-52 w-52 rounded-lg bg-white p-2"/><p className="mt-3 text-center text-xs text-gray-500 dark:text-zinc-400">No WhatsApp, abra Aparelhos conectados e escolha Conectar um aparelho.</p></div>}</AppCard>
        <AppCard className="p-4 sm:p-5"><AppSectionHeader title="Gerenciamento da sessão" description="Identidade e ciclo de vida da conta vinculada a esta unidade."/><div className="mt-4 grid gap-3 sm:grid-cols-2"><Small label="Conta conectada" value={backend.accountName||'Não identificada'}/><Small label="Número" value={backend.accountPhone||'—'}/><Small label="Última conexão" value={backend.lastConnectedAt?dateTime(backend.lastConnectedAt):'—'}/><Small label="QR válido por" value={backend.connectionStatus==='qr'?`${qrSeconds}s`:'—'}/></div>{backend.disconnectReason&&<div className={`mt-3 rounded-lg p-3 text-xs ${backend.disconnectKind==='intentional'?'bg-gray-100 text-gray-600 dark:bg-zinc-800 dark:text-zinc-300':'bg-amber-50 text-amber-800 dark:bg-amber-950/30 dark:text-amber-300'}`}><strong>{backend.disconnectKind==='intentional'?'Desconexão intencional':'Última desconexão'}</strong><p className="mt-1">{backend.disconnectReason}</p></div>}<div className="mt-4 flex flex-wrap gap-2">{backend.connectionStatus==='connected'&&<><AppButton onClick={()=>void connectionAction('reconnect')} disabled={backend.isSending}><RefreshCw className="h-4 w-4"/>Reconectar</AppButton><AppButton onClick={()=>void connectionAction('disconnect')} disabled={backend.isSending}><Unplug className="h-4 w-4"/>Desconectar</AppButton></>}<AppButton onClick={()=>void connectionAction('new-qr')} disabled={backend.isSending||backend.connectionStatus==='connecting'}><QrCode className="h-4 w-4"/>Gerar novo QR</AppButton></div>{backend.connectionStatus==='qr'&&qrSeconds===0&&<p className="mt-3 text-xs font-bold text-red-500">Este QR expirou e não pode mais ser utilizado.</p>}</AppCard>
        <AppCard className="overflow-hidden"><div className="bg-[var(--theme-color)] p-5 text-white"><div className="flex items-start justify-between gap-3"><div><p className="text-xs font-bold uppercase tracking-wider opacity-80">Central de envio</p><h3 className="mt-1 text-xl font-black">{backend.policyBlockReason?'Envio aguardando liberação':backend.campaignStatus==='paused'?'Campanha pausada':backend.isSending?'Campanha em andamento':'Pronto para iniciar'}</h3></div><Send className="h-7 w-7"/></div><div className="mt-5 h-2 overflow-hidden rounded-full bg-black/20"><div className="h-full bg-white transition-all" style={{width:`${percentage}%`}}/></div><div className="mt-2 flex justify-between text-xs"><span>{backend.progress} de {backend.total||parsed.valid.length}</span><span>{backend.isSending?`${percentage}%`:`Estimativa: ${eta}`}</span></div><div className="mt-5 flex gap-2">{backend.isSending?<><AppButton className="flex-1 bg-white text-[var(--theme-color)] hover:bg-white/90" onClick={togglePause}>{backend.campaignStatus==='paused'?<Play className="h-4 w-4"/>:<Pause className="h-4 w-4"/>}{backend.campaignStatus==='paused'?'Retomar':'Pausar'}</AppButton><AppButton className="flex-1 bg-white text-red-600 hover:bg-white/90" onClick={stop}><Pause className="h-4 w-4"/>Cancelar</AppButton></>:<AppButton className="flex-1 bg-white text-[var(--theme-color)] hover:bg-white/90" disabled={serviceAvailability!=='available'||backend.connectionStatus!=='connected'||!parsed.valid.length||!message.trim()||!confirmedOptIn||!consentEvidenceReady} onClick={start}><Play className="h-4 w-4"/>Iniciar campanha</AppButton>}</div></div>{backend.policyBlockReason&&<div className="mx-4 mt-4 rounded-xl border border-amber-300 bg-amber-50 p-3 text-xs text-amber-900 dark:border-amber-800 dark:bg-amber-950/40 dark:text-amber-200"><strong className="block">Envio temporariamente bloqueado</strong><span>{backend.policyBlockReason}</span>{backend.policyBlockedUntil&&<span className="mt-1 block">Liberação estimada: {new Date(backend.policyBlockedUntil).toLocaleString('pt-BR')}.</span>}</div>}<div className="grid grid-cols-3 gap-2 p-4"><Counter label="Processados" value={backend.progress} icon={Clock3}/><Counter label="Enviadas" value={backend.successCount} icon={CheckCircle2}/><Counter label="Falhas" value={backend.errorCount} icon={AlertTriangle}/></div>{feedback&&<p role="status" className="mx-4 mb-4 rounded-lg bg-gray-50 p-3 text-xs font-bold dark:bg-zinc-800">{feedback}</p>}</AppCard>
        <AppCard className="p-4 sm:p-5"><AppSectionHeader title="Registro em tempo real" description="Últimos eventos desta sessão."/><div className="mt-4 max-h-64 space-y-2 overflow-y-auto app-scrollbar">{backend.logs.length?backend.logs.map(log=><div key={log.id} className="flex gap-3 rounded-lg bg-gray-50 p-2 text-xs dark:bg-zinc-800/60"><span className="shrink-0 font-mono text-gray-400">{log.time}</span><span className={log.type==='success'?'text-emerald-600 dark:text-emerald-400':log.type==='warning'?'text-amber-600 dark:text-amber-400':''}>{log.text}</span></div>):<p className="py-8 text-center text-sm text-gray-400">Aguardando atividade.</p>}</div></AppCard>
      </div>
    </div>
    {managedCampaigns.some(item=>['AGUARDANDO_APROVACAO','AGENDADA','NA_FILA'].includes(item.status))&&<AppCard className="p-4 sm:p-5"><AppSectionHeader title="Campanhas programadas" description="Aprove, cancele antes do primeiro envio ou duplique configurações sem reutilizar identificadores."/><div className="mt-4 space-y-2">{managedCampaigns.filter(item=>['AGUARDANDO_APROVACAO','AGENDADA','NA_FILA'].includes(item.status)).map(item=><div key={item.id} className="grid gap-3 rounded-xl border border-gray-200 p-3 dark:border-zinc-800 sm:grid-cols-[minmax(0,1fr)_auto] sm:items-center"><div><strong className="block text-sm">{item.name}</strong><span className="text-xs text-gray-400">{item.status.replaceAll('_',' ')} · {item.scheduledAt?dateTime(item.scheduledAt):'Envio imediato'} · {item.totalRecipients} contatos</span></div><div className="flex flex-wrap gap-2">{item.status==='AGUARDANDO_APROVACAO'&&currentUser?.role==='ADMIN'&&item.createdBy!==currentUser.id&&<AppButton variant="primary" onClick={()=>void approveCampaign(item.id)}><ShieldCheck className="h-4 w-4"/>Aprovar</AppButton>}<AppButton onClick={()=>void duplicateCampaign(item.id)}><RefreshCw className="h-4 w-4"/>Duplicar</AppButton>{!item.firstSentAt&&<AppButton onClick={()=>void cancelScheduledCampaign(item)}><Trash2 className="h-4 w-4"/>Cancelar</AppButton>}</div></div>)}</div></AppCard>}
    <AppCard className="p-4 sm:p-5">
      <AppSectionHeader title="Histórico de campanhas" description="Resumo dos processamentos salvos no sistema."/>
      <div className="mt-4 space-y-2">
        {history.length?currentHistory.map(item=><div key={item.id} className="grid gap-3 rounded-xl border border-gray-200 p-3 dark:border-zinc-800 sm:grid-cols-[minmax(0,1fr)_repeat(5,auto)] sm:items-center"><div><strong className="block text-sm">{item.name}</strong><span className="text-xs text-gray-400">{dateTime(item.createdAt)} · {systemUnits.find(unit=>unit.id===item.unitId)?.name||'Todas as unidades'}</span></div><Small label="Total" value={item.total}/><Small label="Enviadas" value={item.successCount}/><Small label="Falhas" value={item.errorCount}/><AppBadge tone={item.errorCount?'warning':'success'}>{item.status}</AppBadge><AppButton onClick={()=>void exportCampaign(item)}><Download className="h-4 w-4"/>Baixar relatório</AppButton></div>):<AppEmptyState icon={<QrCode/>} title="Nenhum disparo registrado" description="As campanhas concluídas aparecerão aqui."/>}
      </div>
      <Pagination currentPage={currentPage} totalPages={totalPages} onPageChange={goToPage} totalItems={totalItems} />
    </AppCard>
    <div className="flex gap-3 rounded-xl border border-blue-200 bg-blue-50 p-4 text-xs text-blue-800 dark:border-blue-900/50 dark:bg-blue-950/20 dark:text-blue-300"><ShieldCheck className="h-5 w-5 shrink-0"/><p>Use somente contatos com consentimento, mantenha uma opção clara de saída e respeite as políticas do WhatsApp. O sistema limita cada execução a 200 destinatários.</p></div>
  </div>;
}

function Field({label,children}:{label:string;children:React.ReactNode}){return <label><span className="mb-1 block text-xs font-bold text-gray-600 dark:text-zinc-300">{label}</span>{children}</label>}
function Counter({label,value,icon:Icon}:{label:string;value:number;icon:React.ComponentType<{className?:string}>}){return <div className="rounded-xl bg-gray-50 p-3 text-center dark:bg-zinc-800/60"><Icon className="mx-auto h-4 w-4 text-[var(--theme-color)]"/><strong className="mt-1 block text-xl">{value}</strong><span className="text-[10px] text-gray-400">{label}</span></div>}
function Small({label,value}:{label:string;value:React.ReactNode}){return <div><span className="block text-[9px] font-bold uppercase text-gray-400">{label}</span><strong className="text-sm">{value}</strong></div>}
